export interface webhooks {
    batchFinished: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * batch.finished — 批次终态推送
         * @description 关联头：X-Sms-Event-Id 是接收方幂等事件 ID；X-Sms-Correlation-Id 与触发该事件的 HTTP/任务/Outbox 关联 ID 一致。
         *     签名头：X-Sms-Timestamp（Unix秒）、X-Sms-Signature = HMAC-SHA256(callback_secret, timestamp + "." + rawBody) 的 hex。
         *     版本头：X-Sms-Signature-Version 固定为事件创建时的协议版本；X-Sms-Secret-Version 是该事件固化密钥的 key version。密钥轮换不改变既有事件重试。
         *     接收方须验签且校验时间戳偏差 ≤ 300s，返回 2xx 视为成功；否则（含 4xx）按 60/300/900/3600/3600s 重试共5次。
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        /** Format: uuid */
                        event_id: string;
                        /** @constant */
                        event: "batch.finished";
                        batch_no: string;
                        biz_id: string | null;
                        category: string;
                        /** @enum {string} */
                        status: "completed" | "completed_unknown" | "cancelled" | "expired" | "rejected";
                        total: number;
                        delivered: number;
                        failed: number;
                        unknown: number;
                        /** @description 与 unknown 相同的未知数量，供新调用方使用 */
                        unknown_count: number;
                        /** @description completed_unknown 时为 true，不把 unknown 伪装为 failed 或 delivered */
                        manual_resolution_required: boolean;
                        /** Format: date-time */
                        finished_at: string;
                    };
                };
            };
            responses: {
                /** @description 应用侧确认接收 */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
    messageReport: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * message.report — 明细报告聚合推送（应用级开关）
         * @description 按分钟聚合，单次 ≤ 500 条；X-Sms-Event-Id、X-Sms-Correlation-Id、签名与重试策略同 batch.finished。
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        /** Format: uuid */
                        event_id: string;
                        /** @constant */
                        event: "message.report";
                        batch_no: string;
                        biz_id: string | null;
                        items: {
                            /** @description 投递时在内存临时解密生成的明文；callback_task/日志不得持久化，接收方自行保护 */
                            phone?: string;
                            /** @enum {string} */
                            status?: "delivered" | "failed" | "unknown" | "other";
                            report_desc?: string;
                            /** Format: date-time */
                            report_time?: string;
                        }[];
                    };
                };
            };
            responses: {
                /** @description 应用侧确认接收 */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
}
